const {test}=require('node:test'),assert=require('node:assert/strict');
test('seeded Halloween towns replay exactly and conserve every sweet through exhaustion',async()=>{const {createTown,advanceTown}=await import('../halloween/town-sim.mjs');for(const count of [12,18,30]){const a=createTown(43,count),b=createTown(43,count);for(let i=0;i<4000;i++){advanceTown(a,.1);advanceTown(b,.1);}assert.deepEqual(a,b);assert(a.given>0);assert.equal(a.given,a.people.reduce((n,p)=>n+p.sweets,0));assert.equal(a.given+a.houses.reduce((n,h)=>n+h.stock,0),360);assert(a.houses.every(h=>h.stock>=0&&h.initial-h.stock===h.served));assert(a.people.every(p=>p.visits>0));const before=JSON.stringify(a);a.paused=true;advanceTown(a,1);a.paused=false;assert.equal(JSON.stringify(a),before);}});
test('visitors move continuously and only receive gifts at their active household',async()=>{const {createTown,tickTown,housePoint}=await import('../halloween/town-sim.mjs');const t=createTown(92,30);for(let i=0;i<2000;i++){const old=t.people.map(p=>({position:[...p.position],sweets:p.sweets,target:p.target,state:p.state}));tickTown(t,.05);for(const p of t.people){const prev=old[p.id];assert(Math.hypot(p.position[0]-prev.position[0],p.position[1]-prev.position[1])<=p.speed*.05+1e-6);if(p.sweets>prev.sweets){assert.equal(prev.state,'gift');assert.equal(t.houses[prev.target].active,p.id);const q=housePoint(t.houses[prev.target],14.75);assert(Math.hypot(p.position[0]-q[0],p.position[1]-q[1])<1e-6);}}}});
